import { gsap } from 'gsap';
import { ScrollSmoother } from 'gsap/ScrollSmoother.js';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';

export default class Horiz {
  constructor(element) {
    gsap.registerPlugin(ScrollTrigger, ScrollSmoother);
    this.options = {
      hasSkew: false,
      hasPinItems: false,
    };
    this.element = element;
    this.setOptions();
    // this.init();
  }

  init() {
    const scroller = ScrollSmoother.create({
      smooth: 2,
      effects: true,
      smoothTouch: 0.1, //En mobile
      onUpdate: this.onUpdateScroll.bind(this),
      onStop: this.onStopScroll.bind(this),
      ease: 'expo-out',
    });
  }

  onUpdateScroll(self) {
    if (this.options.hasSkew) this.updateSkew(self);
  }

  onStopScroll(self) {
    this.stopSkew(self);
  }

  //Section horizontal

  initHoriz() {
    const sectionHoriz = this.element.querySelector('.js-horiz');
    const panels = sectionHoriz.querySelectorAll('.js-panel');
    const nbPanels = panels.length - 1;
    const buffer = 200;

    this.nbPanels = nbPanels;
    this.initProgress(sectionHoriz, panels);
    this.initParallax(panels);

    this.tween = gsap.to(panels, {
      x: () => -(sectionHoriz.scrollWidth - sectionHoriz.offsetWidth),
      ease: 'none',
      onUpdate: this.onUpdateHoriz.bind(this), // à chaque image : barre de progression + parallaxe
      scrollTrigger: {
        pin: true,
        anticipatePin: 1,
        trigger: sectionHoriz,
        scrub: 1,
        snap: {
          snapTo: 1 / nbPanels,
          directional: false,
          delay: 0.1,
        },
        end: () => '+=' + (sectionHoriz.offsetWidth * nbPanels + buffer),
        invalidateOnRefresh: true,
      },
    });

    this.onUpdateHoriz(); // état de départ : 1er segment allumé, parallaxe en place
  }

  // Barre de progression : un segment par carte, ajouté sous les cartes
  initProgress(sectionHoriz, panels) {
    this.segments = [];
    const progress = document.createElement('div');
    progress.className = 'plans__progress';

    for (let i = 0; i < panels.length; i++) {
      const segment = document.createElement('span');
      progress.appendChild(segment);
      this.segments.push(segment);
    }

    sectionHoriz.appendChild(progress);
  }

  // Parallaxe : la capture de chaque carte bouge un peu moins vite que la carte
  initParallax(panels) {
    this.parallax = [];

    for (let i = 0; i < panels.length; i++) {
      const img = panels[i].querySelector('.media img');
      if (!img) continue;

      gsap.set(img, { scale: 1.15 }); // un peu plus grande que la carte, pour pouvoir bouger sans laisser de vide
      this.parallax.push({ index: i, setX: gsap.quickSetter(img, 'xPercent') });
    }
  }

  onUpdateHoriz() {
    if (!this.tween) return; // GSAP appelle déjà cette fonction pendant la création de l'animation

    // position dans le défilement : 0 = carte 1, 1 = carte 2, … (suit l'animation adoucie par le scrub)
    const position = this.tween.progress() * this.nbPanels;
    const active = Math.round(position);

    for (let i = 0; i < this.segments.length; i++) {
      this.segments[i].classList.toggle('is-done', i <= active);
    }

    for (let i = 0; i < this.parallax.length; i++) {
      const item = this.parallax[i];
      const decalage = gsap.utils.clamp(-6, 6, (position - item.index) * 6);
      item.setX(decalage);
    }
  }

  setOptions() {
    if ('skew' in this.element.dataset) {
      this.options.hasSkew = true;
      this.initSkew();
    }
    if ('pinItems' in this.element.dataset) {
      this.options.hasPinItems = true;
      this.initPins();
    }

    if (this.element.querySelector('.js-horiz')) {
      this.initHoriz();
    }
  }
}
