import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';

export default class Projets {
  constructor(element) {
    gsap.registerPlugin(ScrollTrigger);
    this.options = {
      scrollLength: 4.4, // longueur du scroll
      arrival: 1.5, // durée pour qu'une carte avance
      exit: 0.5, // durée pour qu'une carte sorte
      angle: 14, // angle des cartes
      duration: 300, // secondes affichées par le timecode
    };
    this.element = element;
    this.cards = this.element.querySelectorAll('.js-card');
    this.timecode = this.element.querySelector('.js-timecode');
    this.label = this.element.querySelector('.js-label');
    this.segments = this.element.querySelectorAll('.js-segment');
    this.activeIndex = -1;
    this.init();
  }

  init() {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    this.initTimeline();
    this.initCards();
    this.initFocus();
  }

  //Timeline controls

  initTimeline() {
    this.timeline = gsap.timeline({
      defaults: { ease: 'none' },
      scrollTrigger: {
        trigger: this.element,
        start: 'top top',
        end: () => '+=' + window.innerHeight * this.options.scrollLength,
        pin: true,
        scrub: 1,
        onUpdate: this.onUpdateScroll.bind(this),
      },
    });
  }

  initCards() {
    const last = this.cards.length - 1;

    for (let i = 0; i < this.cards.length; i++) {
      const card = this.cards[i];
      const side = i % 2 === 0 ? -1 : 1;

      gsap.set(card, {
        xPercent: -50,
        yPercent: -50,
        z: -3000,
        rotationY: side * -this.options.angle,
        autoAlpha: 0,
        filter: 'brightness(0.3)',
      });

      this.timeline.to(
        card,
        { z: 0, filter: 'brightness(1)', duration: this.options.arrival },
        i,
      );
      this.timeline.to(card, { autoAlpha: 1, duration: 0.5 }, i - 0.5);

      if (i < last) {
        this.timeline.to(
          card,
          {
            xPercent: -50 + side * 150,
            autoAlpha: 0,
            duration: this.options.exit,
            ease: 'power1.in',
          },
          i + this.options.arrival,
        );
      }
    }
  }

  //Scroll controls

  onUpdateScroll(self) {
    this.updateTimecode(self.progress);
    this.updateActive(self.progress);
  }

  updateTimecode(progress) {
    const total = Math.floor(progress * this.options.duration);
    const pad = (n) => String(n).padStart(2, '0');
    const h = Math.floor(total / 3600);
    const m = Math.floor((total % 3600) / 60);
    const s = total % 60;

    this.timecode.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;
  }

  updateActive(progress) {
    const time = progress * this.timeline.duration();
    const index = gsap.utils.clamp(
      0,
      this.cards.length - 1,
      Math.round(time - this.options.arrival),
    );
    if (index === this.activeIndex) return;
    this.activeIndex = index;

    for (let i = 0; i < this.cards.length; i++) {
      this.cards[i].classList.toggle('is-active', i === index);
    }

    for (let i = 0; i < this.segments.length; i++) {
      this.segments[i].classList.toggle('is-done', i <= index);
    }

    const card = this.cards[index];
    const number = card.querySelector('.top p').textContent.trim();
    const title = card.querySelector('h4').textContent.trim();
    this.label.textContent = `${number} — ${title}`;
  }

  //Focus controls

  // Navigation au clavier (Tab) : amène la carte ciblée à pleine grandeur
  initFocus() {
    for (let i = 0; i < this.cards.length; i++) {
      this.cards[i].addEventListener('focus', this.onFocusCard.bind(this, i));
    }
  }

  onFocusCard(index) {
    const trigger = this.timeline.scrollTrigger;
    const progress = (index + this.options.arrival) / this.timeline.duration();

    window.scrollTo({
      top: trigger.start + (trigger.end - trigger.start) * progress,
    });
  }
}
